import React, { useState, useEffect, useCallback } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import 'react-pdf/dist/esm/Page/AnnotationLayer.css';
import 'react-pdf/dist/esm/Page/TextLayer.css';

// Set up the worker for PDF.js with specific version
pdfjs.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.worker.min.js';

const BookReader = ({ pdfUrl, bookTitle }) => {
  const [numPages, setNumPages] = useState(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [scale, setScale] = useState(1.0);
  const [isFlipping, setIsFlipping] = useState(false);
  const [flipDirection, setFlipDirection] = useState('');
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);
  const [viewportWidth, setViewportWidth] = useState(window.innerWidth);
  const [loadError, setLoadError] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasRetried, setHasRetried] = useState(false);
  const [resolvedUrl, setResolvedUrl] = useState('');
  const [loadAttempts, setLoadAttempts] = useState(0);
  const [useFallback, setUseFallback] = useState(false);

  // Resolve the PDF URL - handle both local src paths and uploaded file URLs
  useEffect(() => {
    if (!pdfUrl) return;

    // Debug output
    console.log('Attempting to load PDF:', pdfUrl);
    
    // Reset states
    setUseFallback(false);
    setLoadError(null);
    setIsLoading(true);
    setLoadAttempts(0);
    
    // Simply pass the URL as is
    setResolvedUrl(pdfUrl);
  }, [pdfUrl]);

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      setViewportWidth(window.innerWidth);
      
      // Adjust scale based on viewport width
      if (window.innerWidth < 768) {
        setScale(0.8); // Smaller screens
      } else if (window.innerWidth < 1024) {
        setScale(1.0); // Medium screens
      } else {
        setScale(1.2); // Larger screens
      }
    };
    
    window.addEventListener('resize', handleResize);
    handleResize(); // Call initially
    
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Functions to handle document loading success and failure
  const onDocumentLoadSuccess = ({ numPages }) => {
    console.log('PDF loaded successfully with', numPages, 'pages');
    setNumPages(numPages);
    setLoadError(null);
    setIsLoading(false);
  };

  const onDocumentLoadError = (error) => {
    console.error('Error loading PDF:', error);
    console.error('Attempted URL:', resolvedUrl);
    setIsLoading(false);
    
    // Increment load attempts
    const newAttempts = loadAttempts + 1;
    setLoadAttempts(newAttempts);
    
    if (newAttempts >= 2) {
      // After multiple attempts, switch to fallback automatically
      console.log("Switching to fallback viewer after multiple failed attempts");
      setUseFallback(true);
    } else {
      // Provide error message
      setLoadError({
        title: 'Error loading PDF',
        message: error.message || 'Failed to load the PDF document.',
        code: 'LOAD_ERROR'
      });
      
      // Auto-retry once
      setTimeout(() => {
        console.log("Auto-retrying PDF load");
        setIsLoading(true);
        setTimeout(() => setIsLoading(false), 1500);
      }, 1000);
    }
  };

  // Functions to handle page navigation
  const goToPrevPage = () => {
    if (pageNumber > 1) {
      setFlipDirection('left');
      setIsFlipping(true);
      setTimeout(() => {
        setPageNumber(pageNumber - 1);
        setTimeout(() => {
          setIsFlipping(false);
        }, 300);
      }, 150);
    }
  };

  const goToNextPage = () => {
    if (pageNumber < numPages) {
      setFlipDirection('right');
      setIsFlipping(true);
      setTimeout(() => {
        setPageNumber(pageNumber + 1);
        setTimeout(() => {
          setIsFlipping(false);
        }, 300);
      }, 150);
    }
  };

  // Touch handlers for mobile swipe
  const onTouchStart = (e) => {
    setTouchStart(e.targetTouches[0].clientX);
  };
  
  const onTouchMove = (e) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };
  
  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > 50;
    const isRightSwipe = distance < -50;
    
    if (isLeftSwipe && pageNumber < numPages) {
      goToNextPage();
    } else if (isRightSwipe && pageNumber > 1) {
      goToPrevPage();
    }
    
    // Reset values
    setTouchStart(null);
    setTouchEnd(null);
  };

  // Jump to specific page
  const jumpToPage = (e) => {
    const pageNum = parseInt(e.target.value);
    if (!isNaN(pageNum) && pageNum >= 1 && pageNum <= numPages) {
      setPageNumber(pageNum);
    }
  };

  // Zoom in and out
  const zoomIn = () => {
    setScale(scale + 0.2);
  };

  const zoomOut = () => {
    setScale(Math.max(0.6, scale - 0.2));
  };

  // Switch to fallback viewer
  const handleSwitchToFallback = () => {
    setUseFallback(true);
  };

  // Retry loading
  const handleRetry = () => {
    setLoadError(null);
    setIsLoading(true);
    
    // Force a slight delay before trying again
    setTimeout(() => {
      setIsLoading(false);
    }, 1000);
  };

  // Render as embedded PDF using iframe as a fallback
  const renderIframeFallback = useCallback(() => {
    return (
      <div className="w-full h-full flex flex-col items-center">
        <div className="bg-yellow-500/20 border border-yellow-500/30 rounded-lg p-3 mb-4 text-yellow-200 text-sm">
          Using fallback PDF viewer. Page flipping animations not available.
        </div>
        <iframe 
          src={pdfUrl}
          className="w-full flex-grow rounded-lg border border-white/10"
          title={`PDF Viewer - ${bookTitle}`}
        />
      </div>
    );
  }, [pdfUrl, bookTitle]);

  // Calculate animation styles
  const getAnimationStyles = () => {
    if (!isFlipping) return {};
    
    const transform = flipDirection === 'right' 
      ? 'translateX(-10%) rotateY(-30deg)' 
      : 'translateX(10%) rotateY(30deg)';
    
    return {
      animation: `${flipDirection === 'right' ? 'flipRight' : 'flipLeft'} 0.5s ease`,
      transform,
      transformOrigin: flipDirection === 'right' ? 'left center' : 'right center',
      boxShadow: flipDirection === 'right' 
        ? '-5px 0 15px rgba(0, 0, 0, 0.25)' 
        : '5px 0 15px rgba(0, 0, 0, 0.25)',
    };
  };

  // Render an error message based on the error type
  const renderErrorMessage = () => {
    if (!loadError) return null;
    
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-[400px] text-red-400 p-6 text-center">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-4 text-red-500/70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
        </svg>
        
        <h3 className="text-xl font-bold mb-2">{loadError.title}</h3>
        <p className="mb-4">{loadError.message}</p>
        
        <div className="flex gap-4">
          <button 
            onClick={handleRetry}
            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
          >
            Try Again
          </button>
          
          <button 
            onClick={handleSwitchToFallback}
            className="px-4 py-2 bg-gray-600 hover:bg-gray-700 text-white rounded-lg transition-colors"
          >
            Try Fallback Viewer
          </button>
        </div>
      </div>
    );
  };

  // Show loading state
  const renderLoadingState = () => (
    <div className="flex items-center justify-center h-full min-h-[400px]">
      <div className="flex flex-col items-center">
        <div className="animate-spin h-12 w-12 border-4 border-blue-500 rounded-full border-t-transparent mb-4"></div>
        <p className="text-white">Loading PDF...</p>
        {loadAttempts > 0 && (
          <p className="text-white/60 text-sm mt-2">Attempt: {loadAttempts + 1}</p>
        )}
        {loadAttempts > 0 && (
          <button
            onClick={handleSwitchToFallback}
            className="mt-4 px-3 py-1 text-sm bg-gray-600 hover:bg-gray-700 text-white rounded-md"
          >
            Use Simple Viewer
          </button>
        )}
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full">
      {/* PDF Reader Header */}
      <div className="mb-4 flex flex-col sm:flex-row justify-between items-start sm:items-center">
        <h3 className="text-lg sm:text-xl font-semibold text-white mb-2 sm:mb-0">{bookTitle || 'PDF Reader'}</h3>
        <div className="flex gap-2">
          {!useFallback && (
            <>
              <button 
                onClick={zoomOut} 
                className="px-2 py-1 text-sm bg-white/10 hover:bg-white/20 text-white rounded-md transition-colors"
                aria-label="Zoom out"
                disabled={loadError || isLoading}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M5 10a1 1 0 011-1h8a1 1 0 110 2H6a1 1 0 01-1-1z" clipRule="evenodd" />
                </svg>
              </button>
              <button 
                onClick={zoomIn} 
                className="px-2 py-1 text-sm bg-white/10 hover:bg-white/20 text-white rounded-md transition-colors"
                aria-label="Zoom in"
                disabled={loadError || isLoading}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
                </svg>
              </button>
            </>
          )}
          {!useFallback && numPages > 0 && (
            <button 
              onClick={handleSwitchToFallback}
              className="px-2 py-1 text-sm bg-white/10 hover:bg-white/20 text-white rounded-md transition-colors"
              aria-label="Simple viewer"
            >
              Simple View
            </button>
          )}
        </div>
      </div>

      {/* Page navigation controls - only shown when PDF is successfully loaded */}
      {!loadError && numPages > 0 && !useFallback && (
        <div className="bg-white/5 backdrop-blur-xl rounded-lg p-4 mb-4 flex flex-wrap justify-between items-center gap-2">
          <div className="flex gap-2">
            <button
              onClick={goToPrevPage}
              disabled={pageNumber <= 1}
              className={`px-3 py-1.5 rounded-md text-white transition-colors ${
                pageNumber <= 1 ? 'bg-gray-700 cursor-not-allowed opacity-50' : 'bg-blue-600 hover:bg-blue-700'
              }`}
            >
              Previous
            </button>
            <button
              onClick={goToNextPage}
              disabled={pageNumber >= numPages}
              className={`px-3 py-1.5 rounded-md text-white transition-colors ${
                pageNumber >= numPages ? 'bg-gray-700 cursor-not-allowed opacity-50' : 'bg-blue-600 hover:bg-blue-700'
              }`}
            >
              Next
            </button>
          </div>
          
          <div className="flex items-center gap-2">
            <span className="text-white">
              Page 
              <input
                type="number"
                min="1"
                max={numPages}
                value={pageNumber}
                onChange={jumpToPage}
                className="w-12 mx-2 px-2 py-1 bg-white/10 border border-white/20 rounded text-center text-white"
              />
              of {numPages || '--'}
            </span>
          </div>
        </div>
      )}

      {/* PDF Document */}
      <div 
        className="flex-grow overflow-y-auto bg-white/5 backdrop-blur-xl p-4 rounded-xl flex justify-center"
        onTouchStart={!useFallback ? onTouchStart : undefined}
        onTouchMove={!useFallback ? onTouchMove : undefined}
        onTouchEnd={!useFallback ? onTouchEnd : undefined}
      >
        {useFallback ? (
          renderIframeFallback()
        ) : isLoading ? (
          renderLoadingState()
        ) : loadError ? (
          renderErrorMessage()
        ) : (
          <div 
            className="relative perspective-1000 transition-transform duration-300"
            style={getAnimationStyles()}
          >
            <Document
              file={resolvedUrl}
              onLoadSuccess={onDocumentLoadSuccess}
              onLoadError={onDocumentLoadError}
              loading={renderLoadingState()}
              error={null} // We're handling errors ourselves now
              options={{
                cMapUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/cmaps/',
                cMapPacked: true,
                standardFontDataUrl: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/standard_fonts/'
              }}
            >
              <Page 
                pageNumber={pageNumber} 
                scale={scale}
                renderTextLayer={true}
                renderAnnotationLayer={true}
                className="shadow-xl"
                key={`page_${pageNumber}`}
                loading={
                  <div className="flex items-center justify-center h-[400px] w-[300px]">
                    <div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent"></div>
                  </div>
                }
                error={
                  <div className="flex items-center justify-center h-[400px] w-[300px] text-red-400">
                    <p>Error loading this page</p>
                  </div>
                }
              />
            </Document>
          </div>
        )}
      </div>

      {/* Mobile page turn indicators - visible only on smaller screens */}
      {!loadError && numPages > 0 && !useFallback && (
        <div className="md:hidden mt-4 text-white/60 text-sm text-center">
          Swipe left or right to turn pages
        </div>
      )}

      {/* CSS for page flip animations */}
      <style jsx>{`
        @keyframes flipRight {
          0% { transform: translateX(0) rotateY(0); }
          50% { transform: translateX(-10%) rotateY(-30deg); }
          100% { transform: translateX(0) rotateY(0); }
        }
        
        @keyframes flipLeft {
          0% { transform: translateX(0) rotateY(0); }
          50% { transform: translateX(10%) rotateY(30deg); }
          100% { transform: translateX(0) rotateY(0); }
        }
        
        .perspective-1000 {
          perspective: 1000px;
        }
      `}</style>
    </div>
  );
};

export default BookReader; 