import React, { useState } from 'react';
import { IconUpload } from '../../assets/icons';

const BookUpload = ({ onBookAdded }) => {
  const [bookTitle, setBookTitle] = useState('');
  const [file, setFile] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  // Handle file selection
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    
    if (selectedFile) {
      // Check if the file is a PDF
      if (selectedFile.type !== 'application/pdf') {
        setErrorMessage('Only PDF files are allowed');
        setFile(null);
        return;
      }
      
      setFile(selectedFile);
      
      // Auto-generate title from filename if empty
      if (!bookTitle) {
        const fileName = selectedFile.name.replace('.pdf', '');
        setBookTitle(fileName);
      }
      
      setErrorMessage('');
    }
  };

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!file) {
      setErrorMessage('Please select a PDF file');
      return;
    }
    
    if (!bookTitle.trim()) {
      setErrorMessage('Please enter a title for the book');
      return;
    }
    
    // Simulate upload process
    setIsUploading(true);
    setErrorMessage('');
    
    // Create a URL for the file
    const fileUrl = URL.createObjectURL(file);
    
    // Simulate API delay
    setTimeout(() => {
      // Call the callback with the new book data
      onBookAdded({
        id: Date.now().toString(),
        title: bookTitle.trim(),
        url: fileUrl,
        filename: file.name,
        uploadDate: new Date().toISOString(),
        size: file.size
      });
      
      // Reset form
      setBookTitle('');
      setFile(null);
      
      // Show success message
      setSuccessMessage('Book added successfully!');
      setTimeout(() => setSuccessMessage(''), 3000);
      
      setIsUploading(false);
    }, 1000);
  };

  return (
    <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 shadow-lg shadow-black/10 border border-white/10">
      <h3 className="text-xl font-semibold text-white mb-4 flex items-center">
        <IconUpload size={22} className="mr-2" />
        Upload New Book
      </h3>
      
      <form onSubmit={handleSubmit}>
        <div className="mb-4">
          <label htmlFor="bookTitle" className="block text-white/80 mb-1">Book Title</label>
          <input
            id="bookTitle"
            type="text"
            value={bookTitle}
            onChange={(e) => setBookTitle(e.target.value)}
            placeholder="Enter book title"
            className="w-full px-4 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors"
          />
        </div>
        
        <div className="mb-4">
          <label htmlFor="pdfFile" className="block text-white/80 mb-1">PDF File</label>
          <div className="relative">
            <input
              id="pdfFile"
              type="file"
              accept="application/pdf"
              onChange={handleFileChange}
              className="hidden"
            />
            <div 
              className={`w-full px-4 py-8 border-2 border-dashed rounded-lg text-center cursor-pointer transition-colors
                ${file ? 'border-green-500 bg-green-500/10' : 'border-white/20 bg-white/5 hover:bg-white/10'}`}
              onClick={() => document.getElementById('pdfFile').click()}
            >
              {file ? (
                <div className="text-white">
                  <div className="font-medium mb-1">{file.name}</div>
                  <div className="text-sm opacity-70">{(file.size / (1024 * 1024)).toFixed(2)} MB</div>
                </div>
              ) : (
                <div className="text-white/70">
                  <IconUpload size={32} className="mx-auto mb-2" />
                  <div>Drop your PDF here or click to browse</div>
                  <div className="text-sm mt-1 text-white/50">Only PDF files are supported</div>
                </div>
              )}
            </div>
          </div>
        </div>
        
        {errorMessage && (
          <div className="mb-4 p-3 bg-red-500/20 border border-red-500/30 rounded-lg text-red-300">
            {errorMessage}
          </div>
        )}
        
        {successMessage && (
          <div className="mb-4 p-3 bg-green-500/20 border border-green-500/30 rounded-lg text-green-300">
            {successMessage}
          </div>
        )}
        
        <button
          type="submit"
          disabled={isUploading}
          className={`w-full py-3 rounded-lg font-medium flex items-center justify-center transition-colors
            ${isUploading
              ? 'bg-blue-500/50 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700'
            } text-white`}
        >
          {isUploading ? (
            <>
              <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Uploading...
            </>
          ) : 'Upload Book'}
        </button>
      </form>
    </div>
  );
};

export default BookUpload; 