import React, { useState, useEffect } from 'react';
import { IconBook } from '../../assets/icons';
import BookReader from './BookReader';
import BookList from './BookList';
import BookUpload from './BookUpload';

// Use public directory path for accessing files
const BOOK_PATH = '/books/';

const Books = () => {
  // State for books data
  const [books, setBooks] = useState([]);
  const [selectedBook, setSelectedBook] = useState(null);
  const [isUploadMode, setIsUploadMode] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [fileChecks, setFileChecks] = useState({});
  const [showReader, setShowReader] = useState(false);
  const [currentBook, setCurrentBook] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredBooks, setFilteredBooks] = useState([]);
  
  // Check if file exists before passing to reader
  const checkFileExists = async (url) => {
    try {
      // Skip check for blob URLs (user uploads)
      if (url.startsWith('blob:')) return true;
      
      // Check if we've already verified this file
      if (fileChecks[url] !== undefined) {
        return fileChecks[url];
      }
      
      console.log('Checking file exists:', url);
      const response = await fetch(url, { method: 'HEAD' });
      const exists = response.ok;
      
      // Store result in cache
      setFileChecks(prev => ({...prev, [url]: exists}));
      
      if (!exists) {
        console.error(`File not found: ${url} (HTTP ${response.status})`);
      }
      
      return exists;
    } catch (error) {
      console.error('Error checking file existence:', error);
      return false;
    }
  };
  
  // Load books from both localStorage and the books folder
  useEffect(() => {
    const loadBooks = async () => {
      setIsLoading(true);
      
      try {
        // First, load user-uploaded books from localStorage
        const userBooks = [];
        const savedBooks = localStorage.getItem('books');
        
        if (savedBooks) {
          try {
            const parsedBooks = JSON.parse(savedBooks);
            userBooks.push(...parsedBooks);
          } catch (error) {
            console.error('Error loading books from localStorage:', error);
          }
        }
        
        // Then, load pre-loaded books directly from the folder
        try {
          // List of PDF files located in the books folder
          const macOSBooks = [
            {
              id: 'book-0',
              title: 'Simple Test PDF',
              filename: 'Simple_Test.pdf',
              author: 'Track Your Study Team',
              description: 'A simple test PDF file',
              addedDate: '2024-03-18'
            },
            {
              id: 'book-1',
              title: 'Personal Jokes in Aristophanes',
              filename: 'Personal Jokes in Aristophanes FS Halliwell, Worcester College D Phil The material of this thesis - PDF Room.pdf',
              author: 'FS Halliwell',
              description: 'Worcester College D Phil The material of this thesis',
              addedDate: '2023-10-15'
            },
            {
              id: 'book-2',
              title: 'Yo Mama Jokes Encyclopedia',
              filename: 'Yo Mama Jokes EncyclopediaThe Worlds Funniest Yo Momma Jokes! - PDF Room.pdf',
              author: 'PDF Room',
              description: 'The Worlds Funniest Yo Momma Jokes!',
              addedDate: '2023-11-22'
            },
            {
              id: 'book-3',
              title: 'The Funniest Five Thousand Jokes',
              filename: 'The Funniest Five Thousand Jokes - PDF Room.pdf',
              author: 'PDF Room',
              description: 'Collection of five thousand funny jokes',
              addedDate: '2023-12-05'
            },
            {
              id: 'book-4',
              title: 'The Ginormous Book of Dirty Jokes',
              filename: 'The Ginormous Book of Dirty Jokes_ Over 1,000 Sick, Filthy and X-Rated Jokes - PDF Room.pdf',
              author: 'PDF Room',
              description: 'Over 1,000 Sick, Filthy and X-Rated Jokes',
              addedDate: '2024-01-10'
            },
            {
              id: 'book-5',
              title: 'The Best Joke Book Period',
              filename: 'The Best Joke Book Period_ Hundreds of the Funniest, Silliest, Most Ridiculous Jokes Ever - PDF Room.pdf',
              author: 'PDF Room',
              description: 'Hundreds of the Funniest, Silliest, Most Ridiculous Jokes Ever',
              addedDate: '2024-01-18'
            },
            {
              id: 'book-6',
              title: 'The Serious Guide to Joke Writing',
              filename: 'The Serious Guide to Joke Writing_ How To Say Something Funny About Anything - PDF Room.pdf',
              author: 'PDF Room',
              description: 'How To Say Something Funny About Anything',
              addedDate: '2024-02-12'
            },
            {
              id: 'book-7',
              title: 'Batman: The Killing Joke',
              filename: 'Batman_ The Killing Joke - PDF Room.pdf',
              author: 'PDF Room',
              description: 'Batman graphic novel',
              addedDate: '2024-02-25'
            },
            {
              id: 'book-8',
              title: 'Manga Comics: The Breaker New Waves',
              filename: 'Manga Comics_ the-breaker-new-waves-4 - PDF Room.pdf',
              author: 'PDF Room',
              description: 'The Breaker New Waves 4',
              addedDate: '2024-03-10'
            }
          ];
          
          // Transform the preloaded books to match our app's book format
          const processedPreloadedBooks = macOSBooks.map(book => {
            return {
              id: book.id,
              title: book.title,
              url: BOOK_PATH + encodeURIComponent(book.filename),
              filename: book.filename,
              author: book.author || 'Unknown',
              description: book.description || '',
              uploadDate: book.addedDate || new Date().toISOString(),
              isPreloaded: true
            };
          });
          
          // Combine both sources, with pre-loaded books first
          const allBooks = [...processedPreloadedBooks, ...userBooks];
          setBooks(allBooks);
          setFilteredBooks(allBooks);
          
          // Select the first book if available and none selected
          if (allBooks.length > 0 && !selectedBook) {
            setSelectedBook(allBooks[0]);
          }
          
          // Check which files actually exist in the public folder (in background)
          console.log("Checking which PDF files exist in the public folder...");
          processedPreloadedBooks.forEach(book => {
            checkFileExists(book.url).then(exists => {
              if (!exists) {
                console.warn(`File not found: ${book.filename}`);
              }
            });
          });
        } catch (error) {
          console.error('Error loading pre-loaded books:', error);
          setError('Failed to load pre-loaded books. Using only user books.');
          
          // If pre-loaded books fail, still use user books
          setBooks(userBooks);
          setFilteredBooks(userBooks);
          
          // Select the first book if available and none selected
          if (userBooks.length > 0 && !selectedBook) {
            setSelectedBook(userBooks[0]);
          }
        }
      } finally {
        setIsLoading(false);
      }
    };
    
    loadBooks();
  }, []);
  
  // Save user books to localStorage whenever they are added/removed
  // Note: We only save user-uploaded books, not preloaded ones
  useEffect(() => {
    const userBooks = books.filter(book => !book.isPreloaded);
    localStorage.setItem('books', JSON.stringify(userBooks));
  }, [books]);
  
  // Apply search filtering to books
  useEffect(() => {
    if (!searchTerm.trim()) {
      setFilteredBooks(books);
    } else {
      const searchLower = searchTerm.toLowerCase();
      const filtered = books.filter(book => 
        book.title.toLowerCase().includes(searchLower) ||
        book.filename.toLowerCase().includes(searchLower) ||
        (book.author && book.author.toLowerCase().includes(searchLower)) ||
        (book.description && book.description.toLowerCase().includes(searchLower))
      );
      setFilteredBooks(filtered);
    }
  }, [books, searchTerm]);
  
  // Handle book selection
  const handleBookSelect = (book) => {
    setSelectedBook(book);
    setIsUploadMode(false);
  };
  
  // Handle adding a new book
  const handleBookAdded = (newBook) => {
    const updatedBooks = [...books, newBook];
    setBooks(updatedBooks);
    setSelectedBook(newBook);
    setIsUploadMode(false);
  };
  
  // Toggle upload mode
  const toggleUploadMode = () => {
    setIsUploadMode(!isUploadMode);
  };

  // Function to get the URL for a PDF file
  const getPdfUrl = (filename) => {
    if (!filename) return '';
    
    // For simplicity, just use the direct path to the PDF
    const url = `/books/${encodeURIComponent(filename)}`;
    console.log(`Constructed PDF URL for ${filename}:`, url);
    return url;
  };

  const openBook = (book) => {
    // Get and set the PDF URL
    const pdfUrl = getPdfUrl(book.filename);
    console.log('Opening book with URL:', pdfUrl);
    
    // Set the current book and show the reader
    setCurrentBook(book);
    setShowReader(true);
  };

  // Handle search term changes
  const handleSearchChange = (term) => {
    setSearchTerm(term);
  };
  
  // Expose openBook function for BookList component
  useEffect(() => {
    window.openBook = openBook;
    return () => {
      delete window.openBook;
    };
  }, []);

  return (
    <div className="flex flex-col h-full">
      {/* Page Header */}
      <div className="mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center">
        <h2 className="text-2xl font-bold text-white mb-4 sm:mb-0 flex items-center">
          <IconBook size={28} className="mr-3" /> 
          Books
        </h2>
        
        <button
          onClick={toggleUploadMode}
          className={`px-4 py-2 rounded-lg text-white font-medium transition-colors ${
            isUploadMode 
              ? 'bg-indigo-600 hover:bg-indigo-700'
              : 'bg-blue-600 hover:bg-blue-700'
          }`}
        >
          {isUploadMode ? 'Back to Reading' : 'Upload PDF'}
        </button>
      </div>
      
      {/* Error message if book loading failed */}
      {error && (
        <div className="mb-4 p-3 bg-red-500/20 border border-red-500/30 rounded-lg text-red-300">
          {error}
        </div>
      )}
      
      {isLoading ? (
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin h-8 w-8 border-4 border-blue-500 rounded-full border-t-transparent"></div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col lg:flex-row gap-6">
          {/* Sidebar with book list */}
          <div className="lg:w-1/3 xl:w-1/4 space-y-6">
            <BookList 
              books={filteredBooks} 
              fileChecks={fileChecks}
              onSearchChange={handleSearchChange}
            />
          </div>
          
          {/* Main content area - either book reader or upload form */}
          <div className="flex-1">
            {isUploadMode ? (
              <BookUpload onBookAdded={handleBookAdded} />
            ) : selectedBook ? (
              <BookReader pdfUrl={selectedBook.url} bookTitle={selectedBook.title} />
            ) : (
              <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 shadow-lg shadow-black/10 border border-white/10 flex items-center justify-center h-full">
                <div className="text-center text-white/70">
                  <IconBook size={48} className="mx-auto mb-4 opacity-50" />
                  <h3 className="text-xl font-semibold mb-2">No book selected</h3>
                  <p>Select a book from the list or upload a new one to start reading</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Book Reader Modal */}
      {showReader && currentBook && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="w-full max-w-5xl h-[90vh] bg-gray-900/90 backdrop-blur-xl rounded-xl overflow-hidden shadow-2xl flex flex-col border border-white/10">
            {/* Reader Header */}
            <div className="p-4 flex justify-between items-center border-b border-white/10">
              <h2 className="text-xl font-semibold text-white">{currentBook.title}</h2>
              <button 
                onClick={() => setShowReader(false)}
                className="text-white p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            
            {/* Reader Content */}
            <div className="flex-grow p-4 overflow-hidden">
              <BookReader 
                pdfUrl={getPdfUrl(currentBook.filename)} 
                bookTitle={currentBook.title} 
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Books; 