import React, { useEffect, useState } from 'react';

const PersonalizedGreeting = ({ className = '' }) => {
  const [greeting, setGreeting] = useState('');
  const [icon, setIcon] = useState('');
  const [username, setUsername] = useState('Rahul');
  const [timeBasedColor, setTimeBasedColor] = useState('from-blue-300 to-purple-400');
  const [timeBasedGlow, setTimeBasedGlow] = useState('text-shadow-blue-glow');
  const [glowColor1, setGlowColor1] = useState('bg-blue-500');
  const [glowColor2, setGlowColor2] = useState('bg-purple-500');
  
  useEffect(() => {
    // Get current hour
    const currentHour = new Date().getHours();
    
    // Determine greeting based on time of day
    if (currentHour >= 5 && currentHour < 12) {
      setGreeting('Good Morning');
      setIcon('☀️');
      setTimeBasedColor('from-yellow-300 to-orange-400');
      setTimeBasedGlow('text-shadow-glow');
      setGlowColor1('bg-yellow-500');
      setGlowColor2('bg-orange-500');
    } else if (currentHour >= 12 && currentHour < 18) {
      setGreeting('Good Afternoon');
      setIcon('🌤️');
      setTimeBasedColor('from-blue-300 to-cyan-400');
      setTimeBasedGlow('text-shadow-blue-glow');
      setGlowColor1('bg-blue-500');
      setGlowColor2('bg-cyan-500');
    } else {
      setGreeting('Good Evening');
      setIcon('🌙');
      setTimeBasedColor('from-indigo-300 to-purple-400');
      setTimeBasedGlow('text-shadow-purple-glow');
      setGlowColor1('bg-indigo-500');
      setGlowColor2('bg-purple-500');
    }
    
    // In a real app, you would fetch the user's name from context/state
    // For now, we'll use a placeholder name
  }, []);
  
  return (
    <div className={`bg-white/5 backdrop-blur-xl rounded-2xl p-6 shadow-lg shadow-black/10 border border-white/10 relative overflow-hidden ${className}`}>
      {/* Subtle glow effect */}
      <div 
        className={`absolute -top-20 -left-20 w-40 h-40 ${glowColor1} rounded-full opacity-20 blur-3xl animate-pulse-slow`}
        style={{ animationDelay: '0.5s' }}
      ></div>
      <div 
        className={`absolute -bottom-20 -right-20 w-40 h-40 ${glowColor2} rounded-full opacity-10 blur-3xl animate-pulse-slow`}
      ></div>
      
      {/* Content */}
      <div className="relative z-10 animate-fade-in">
        <h1 className="flex flex-wrap items-center text-2xl font-bold sm:text-3xl md:text-4xl">
          <span className="text-white text-shadow-glow bg-gradient-to-r from-white to-white/70 bg-clip-text mr-2">
            {greeting},
          </span>
          <span className={`text-transparent bg-gradient-to-r ${timeBasedColor} bg-clip-text ${timeBasedGlow}`}>
            {username}
          </span>
          <span className="ml-3 text-xl sm:text-2xl animate-float">{icon}</span>
        </h1>
        <div className="mt-3 max-w-md">
          <p className="text-white/60 text-sm sm:text-base">
            Track your studies, manage tasks, and stay on top of your academic goals.
          </p>
        </div>
        <div className={`w-20 h-0.5 bg-gradient-to-r ${timeBasedColor} mt-4 rounded-full`}></div>
      </div>
    </div>
  );
};

export default PersonalizedGreeting; 