import React, { useState, useEffect } from 'react';
import { IconBook, IconSearch } from '../../assets/icons';

const BookList = ({ books, fileChecks, onSearchChange }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredBooks, setFilteredBooks] = useState(books);

  // Update filtered books when books array or search term changes
  useEffect(() => {
    if (!searchTerm.trim()) {
      setFilteredBooks(books);
    } else {
      const searchTermLower = searchTerm.toLowerCase();
      const filtered = books.filter(book => 
        book.title.toLowerCase().includes(searchTermLower) ||
        book.filename?.toLowerCase().includes(searchTermLower)
      );
      setFilteredBooks(filtered);
    }
  }, [books, searchTerm]);

  // Handle search change and call parent handler
  const handleSearchChange = (e) => {
    const value = e.target.value;
    setSearchTerm(value);
    if (onSearchChange) {
      onSearchChange(value);
    }
  };

  // Clear search term
  const clearSearch = () => {
    setSearchTerm('');
    if (onSearchChange) {
      onSearchChange('');
    }
  };

  // Format file size for display
  const formatFileSize = (bytes) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  // Format upload date for display
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString(undefined, { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  return (
    <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 shadow-lg shadow-black/10 border border-white/10">
      <h3 className="text-xl font-semibold text-white mb-4 flex items-center">
        <IconBook size={22} className="mr-2" />
        Your Books
      </h3>
      
      {/* Search bar */}
      <div className="mb-4 relative">
        <div className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">
          <IconSearch size={18} />
        </div>
        <input
          type="text"
          value={searchTerm}
          onChange={handleSearchChange}
          placeholder="Search books..."
          className="w-full pl-10 pr-10 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors"
        />
        {searchTerm && (
          <button 
            onClick={clearSearch}
            className="absolute right-3 top-1/2 transform -translate-y-1/2 text-white/50 hover:text-white"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
            </svg>
          </button>
        )}
      </div>
      
      {/* Book list */}
      <div className="space-y-3 max-h-96 overflow-y-auto pr-2">
        {filteredBooks.length > 0 ? (
          filteredBooks.map(book => (
            <div 
              key={book.id}
              onClick={() => window.openBook && window.openBook(book)}
              className="p-3 rounded-lg cursor-pointer transition-colors bg-white/5 border border-white/10 hover:bg-white/10"
            >
              <div className="flex items-start">
                <div className="p-2 bg-white/10 rounded-lg mr-3">
                  <IconBook size={24} className="text-white/70" />
                </div>
                
                <div className="flex-grow">
                  <h4 className="text-white font-medium truncate">{book.title}</h4>
                  
                  <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-xs text-white/60">
                    <span className="inline-flex items-center">
                      <svg className="h-3 w-3 mr-1" fill="currentColor" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
                        <path d="M9 4.804A7.968 7.968 0 005.5 4c-1.255 0-2.443.29-3.5.804v10A7.969 7.969 0 015.5 14c1.669 0 3.218.51 4.5 1.385A7.962 7.962 0 0114.5 14c1.255 0 2.443.29 3.5.804v-10A7.968 7.968 0 0014.5 4c-1.255 0-2.443.29-3.5.804V12a1 1 0 11-2 0V4.804z"></path>
                      </svg>
                      {book.filename}
                    </span>
                    
                    {book.uploadDate && (
                      <span className="inline-flex items-center">
                        <svg className="h-3 w-3 mr-1" fill="currentColor" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
                          <path fillRule="evenodd" d="M6 2a1 1 0 00-1 1v1H4a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V6a2 2 0 00-2-2h-1V3a1 1 0 10-2 0v1H7V3a1 1 0 00-1-1zm0 5a1 1 0 000 2h8a1 1 0 100-2H6z" clipRule="evenodd"></path>
                        </svg>
                        {formatDate(book.uploadDate)}
                      </span>
                    )}
                    
                    {book.size && (
                      <span className="inline-flex items-center">
                        <svg className="h-3 w-3 mr-1" fill="currentColor" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
                          <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd"></path>
                        </svg>
                        {formatFileSize(book.size)}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="py-8 text-center text-white/60">
            {books.length > 0 ? (
              <div>
                <div className="text-lg mb-1">No matching books found</div>
                <div className="text-sm">Try adjusting your search term</div>
              </div>
            ) : (
              <div>
                <div className="text-lg mb-1">No books available</div>
                <div className="text-sm">Upload your first PDF to get started</div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default BookList; 