import React from 'react';
import {
  IconDashboard,
  IconMessages,
  IconNotifications,
  IconProfile,
  IconTasks,
  IconPomodoro,
  IconBook
} from '../../assets/icons';

const MobileNavigation = ({ activeTab, setActiveTab }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <IconDashboard size={22} /> },
    { id: 'tasks', label: 'Tasks', icon: <IconTasks size={22} /> },
    { id: 'pomodoro', label: 'Pomodoro', icon: <IconPomodoro size={22} /> },
    { id: 'books', label: 'Books', icon: <IconBook size={22} /> },
    { id: 'messages', label: 'Messages', icon: <IconMessages size={22} /> },
    { id: 'notifications', label: 'Notifications', icon: <IconNotifications size={22} /> }
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 h-16 bg-black/40 backdrop-blur-xl border-t border-white/10 flex justify-around items-center z-50 safe-bottom pb-safe">
      {navItems.map(item => (
        <button
          key={item.id}
          className={`flex flex-col items-center justify-center px-2 py-2 rounded-lg transition-all duration-300 ${
            activeTab === item.id 
              ? 'text-white bg-white/15' 
              : 'text-white/60 hover:text-white'
          }`}
          onClick={() => setActiveTab(item.id)}
        >
          <span className="mb-1">{item.icon}</span>
          <span className="text-xs font-medium">{item.label}</span>
        </button>
      ))}
    </div>
  );
};

export default MobileNavigation; 