import React, { useState, useEffect } from 'react';
import { IconChecklist, IconPendingTasks, IconInProgress } from '../../assets/icons';

const TaskManagement = () => {
  const [tasks, setTasks] = useState([
    {
      id: 1,
      title: 'Complete Math Assignment',
      description: 'Finish calculus problems 1-20',
      dueDate: '2023-03-25',
      difficulty: 'medium',
      priority: 'high',
      completed: false,
      progress: 0
    },
    {
      id: 2,
      title: 'Study for Physics Exam',
      description: 'Review chapters 5-8 and practice problems',
      dueDate: '2023-03-30',
      difficulty: 'hard',
      priority: 'urgent',
      completed: false,
      progress: 25
    },
    {
      id: 3,
      title: 'Read Literature Assignment',
      description: 'Read chapters 10-12 of The Great Gatsby',
      dueDate: '2023-03-22',
      difficulty: 'easy',
      priority: 'medium',
      completed: true,
      progress: 100
    }
  ]);

  const [newTask, setNewTask] = useState({
    title: '',
    description: '',
    dueDate: '',
    difficulty: 'medium',
    priority: 'medium',
    completed: false,
    progress: 0
  });

  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTaskId, setEditingTaskId] = useState(null);
  const [completionStats, setCompletionStats] = useState({ total: 0, completed: 0, percentage: 0 });

  useEffect(() => {
    // Calculate completion statistics
    const total = tasks.length;
    const completed = tasks.filter(task => task.completed).length;
    const percentage = total > 0 ? Math.round((completed / total) * 100) : 0;
    
    setCompletionStats({ total, completed, percentage });
  }, [tasks]);

  // Priority color mapping
  const priorityColors = {
    low: { bg: 'bg-blue-500', text: 'text-blue-500', border: 'border-blue-500', hover: 'hover:bg-blue-600' },
    medium: { bg: 'bg-yellow-500', text: 'text-yellow-500', border: 'border-yellow-500', hover: 'hover:bg-yellow-600' },
    high: { bg: 'bg-orange-500', text: 'text-orange-500', border: 'border-orange-500', hover: 'hover:bg-orange-600' },
    urgent: { bg: 'bg-red-500', text: 'text-red-500', border: 'border-red-500', hover: 'hover:bg-red-600' }
  };

  // Difficulty level mapping
  const difficultyMapping = {
    easy: { icon: '🟢', label: 'Easy', class: 'text-green-400' },
    medium: { icon: '🟡', label: 'Medium', class: 'text-yellow-400' },
    hard: { icon: '🟠', label: 'Hard', class: 'text-orange-400' },
    expert: { icon: '🔴', label: 'Expert', class: 'text-red-400' }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewTask(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!newTask.title) return;
    
    if (editingTaskId) {
      // Update existing task
      setTasks(tasks.map(task => 
        task.id === editingTaskId ? { ...newTask, id: editingTaskId } : task
      ));
      setEditingTaskId(null);
    } else {
      // Add new task
      const id = Math.max(0, ...tasks.map(t => t.id)) + 1;
      setTasks([...tasks, { ...newTask, id }]);
    }
    
    // Reset form
    setNewTask({
      title: '',
      description: '',
      dueDate: '',
      difficulty: 'medium',
      priority: 'medium',
      completed: false,
      progress: 0
    });
    
    setIsFormOpen(false);
  };

  const handleProgressChange = (id, progress) => {
    setTasks(tasks.map(task => {
      if (task.id === id) {
        const completed = progress === 100;
        return { ...task, progress, completed };
      }
      return task;
    }));
  };

  const handleEdit = (task) => {
    setNewTask({ ...task });
    setEditingTaskId(task.id);
    setIsFormOpen(true);
  };

  const handleDelete = (id) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  const toggleTaskCompletion = (id) => {
    setTasks(tasks.map(task => {
      if (task.id === id) {
        const completed = !task.completed;
        return { 
          ...task, 
          completed,
          progress: completed ? 100 : 0
        };
      }
      return task;
    }));
  };

  // Calculate days remaining till due date
  const getDaysRemaining = (dueDate) => {
    const today = new Date();
    const due = new Date(dueDate);
    const diffTime = due - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  };

  // Format the due date display
  const formatDueDate = (dueDate) => {
    const date = new Date(dueDate);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  return (
    <div className="space-y-6">
      {/* Header section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center">
            <IconChecklist size={28} className="mr-3" /> Task Management
          </h1>
          <p className="text-white/60 mt-1">Organize and track your study tasks</p>
        </div>
        
        <button 
          onClick={() => {
            setIsFormOpen(true);
            setEditingTaskId(null);
            setNewTask({
              title: '',
              description: '',
              dueDate: '',
              difficulty: 'medium',
              priority: 'medium',
              completed: false,
              progress: 0
            });
          }}
          className="px-4 py-2 bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl text-white font-medium shadow-lg shadow-blue-500/30 hover:shadow-xl hover:shadow-blue-500/40 hover:-translate-y-0.5 transition-all duration-300 flex items-center"
        >
          <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
          </svg>
          Add New Task
        </button>
      </div>

      {/* Progress stats */}
      <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 shadow-lg shadow-black/10 border border-white/10">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-4">
          <h3 className="text-xl font-semibold text-white mb-2 sm:mb-0">Study Progress</h3>
          <div className="flex items-center">
            <span className="text-white/60 mr-2">
              {completionStats.completed}/{completionStats.total} tasks completed
            </span>
            <span className="bg-white/10 px-2 py-1 rounded-lg text-sm font-medium text-white">
              {completionStats.percentage}%
            </span>
          </div>
        </div>
        
        <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-blue-400 to-blue-600 rounded-full transition-all duration-500 ease-out"
            style={{ width: `${completionStats.percentage}%` }}
          ></div>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mt-6">
          <div className="bg-white/5 p-4 rounded-xl flex items-center">
            <div className="w-10 h-10 rounded-lg bg-blue-500/20 flex items-center justify-center text-blue-400 mr-3">
              <IconPendingTasks size={20} />
            </div>
            <div>
              <p className="text-white/60 text-sm">Pending</p>
              <p className="text-xl font-semibold text-white">{tasks.filter(t => !t.completed).length}</p>
            </div>
          </div>
          
          <div className="bg-white/5 p-4 rounded-xl flex items-center">
            <div className="w-10 h-10 rounded-lg bg-yellow-500/20 flex items-center justify-center text-yellow-400 mr-3">
              <IconInProgress size={20} />
            </div>
            <div>
              <p className="text-white/60 text-sm">In Progress</p>
              <p className="text-xl font-semibold text-white">{tasks.filter(t => !t.completed && t.progress > 0).length}</p>
            </div>
          </div>
          
          <div className="bg-white/5 p-4 rounded-xl flex items-center">
            <div className="w-10 h-10 rounded-lg bg-green-500/20 flex items-center justify-center text-green-400 mr-3">
              <IconChecklist size={20} />
            </div>
            <div>
              <p className="text-white/60 text-sm">Completed</p>
              <p className="text-xl font-semibold text-white">{tasks.filter(t => t.completed).length}</p>
            </div>
          </div>
        </div>
      </div>
      
      {/* Add/Edit Task Form */}
      {isFormOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div 
            className="bg-gray-800/95 rounded-2xl p-6 shadow-2xl max-w-lg w-full border border-white/10 animate-scale-up"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-semibold text-white">
                {editingTaskId ? 'Edit Task' : 'New Task'}
              </h3>
              <button 
                className="text-white/60 hover:text-white transition-colors"
                onClick={() => setIsFormOpen(false)}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-white/60 mb-1 text-sm">Task Title</label>
                <input 
                  type="text"
                  name="title"
                  value={newTask.title}
                  onChange={handleInputChange}
                  placeholder="Enter task title"
                  className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
              </div>
              
              <div>
                <label className="block text-white/60 mb-1 text-sm">Description</label>
                <textarea
                  name="description"
                  value={newTask.description}
                  onChange={handleInputChange}
                  placeholder="Enter task description"
                  rows="3"
                  className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
                ></textarea>
              </div>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-white/60 mb-1 text-sm">Due Date</label>
                  <input 
                    type="date"
                    name="dueDate"
                    value={newTask.dueDate}
                    onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>
                
                <div>
                  <label className="block text-white/60 mb-1 text-sm">Progress</label>
                  <div className="flex items-center">
                    <input 
                      type="range"
                      name="progress"
                      min="0"
                      max="100"
                      step="25"
                      value={newTask.progress}
                      onChange={handleInputChange}
                      className="w-full accent-blue-500"
                    />
                    <span className="ml-2 text-white min-w-[40px] text-right">{newTask.progress}%</span>
                  </div>
                </div>
              </div>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-white/60 mb-1 text-sm">Difficulty</label>
                  <select
                    name="difficulty"
                    value={newTask.difficulty}
                    onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="easy">Easy</option>
                    <option value="medium">Medium</option>
                    <option value="hard">Hard</option>
                    <option value="expert">Expert</option>
                  </select>
                </div>
                
                <div>
                  <label className="block text-white/60 mb-1 text-sm">Priority</label>
                  <select
                    name="priority"
                    value={newTask.priority}
                    onChange={handleInputChange}
                    className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="low">Low</option>
                    <option value="medium">Medium</option>
                    <option value="high">High</option>
                    <option value="urgent">Urgent</option>
                  </select>
                </div>
              </div>
              
              <div className="flex justify-end pt-4 space-x-3">
                <button
                  type="button"
                  onClick={() => setIsFormOpen(false)}
                  className="px-4 py-2 border border-white/10 rounded-xl text-white hover:bg-white/10 transition-colors duration-300"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl text-white font-medium shadow-md hover:shadow-lg transition-all duration-300"
                >
                  {editingTaskId ? 'Update Task' : 'Add Task'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
      
      {/* Task list */}
      <div className="space-y-4">
        {tasks.length === 0 ? (
          <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-8 shadow-lg shadow-black/10 border border-white/10 text-center">
            <svg className="w-16 h-16 text-white/20 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
            <p className="text-white/60">No tasks yet. Create your first task to get started!</p>
          </div>
        ) : (
          tasks.map(task => {
            const daysRemaining = getDaysRemaining(task.dueDate);
            const isOverdue = daysRemaining < 0 && !task.completed;
            
            return (
              <div 
                key={task.id}
                className={`bg-white/5 backdrop-blur-xl rounded-2xl p-5 shadow-lg shadow-black/10 border border-white/10 transition-all duration-300 hover:bg-white/10 hover:border-white/20 ${task.completed ? 'opacity-70' : ''}`}
              >
                <div className="flex items-start">
                  <div className="mr-3 mt-1">
                    <button
                      onClick={() => toggleTaskCompletion(task.id)}
                      className={`w-6 h-6 rounded-md border transition-colors duration-300 flex items-center justify-center ${
                        task.completed 
                          ? 'bg-green-500 border-green-500 text-white' 
                          : 'border-white/30 hover:border-white/50'
                      }`}
                    >
                      {task.completed && (
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                        </svg>
                      )}
                    </button>
                  </div>
                  
                  <div className="flex-grow">
                    <div className="flex flex-wrap items-start justify-between mb-2">
                      <h3 className={`text-lg font-medium ${task.completed ? 'text-white/60 line-through' : 'text-white'}`}>
                        {task.title}
                      </h3>
                      
                      <div className="flex items-center space-x-2 mt-1 sm:mt-0">
                        <span className={`px-2 py-1 rounded-md text-xs font-medium ${priorityColors[task.priority].bg} bg-opacity-20 ${priorityColors[task.priority].text}`}>
                          {task.priority.charAt(0).toUpperCase() + task.priority.slice(1)}
                        </span>
                        
                        <span className={`flex items-center px-2 py-1 rounded-md text-xs font-medium ${difficultyMapping[task.difficulty].class} bg-opacity-10 bg-white`}>
                          <span className="mr-1">{difficultyMapping[task.difficulty].icon}</span>
                          {difficultyMapping[task.difficulty].label}
                        </span>
                        
                        {task.dueDate && (
                          <span className={`px-2 py-1 rounded-md text-xs font-medium ${
                            isOverdue
                              ? 'bg-red-500/20 text-red-400'
                              : daysRemaining <= 3 && !task.completed
                                ? 'bg-orange-500/20 text-orange-400'
                                : 'bg-white/10 text-white/60'
                          }`}>
                            {isOverdue 
                              ? `Overdue by ${Math.abs(daysRemaining)} day${Math.abs(daysRemaining) !== 1 ? 's' : ''}` 
                              : daysRemaining === 0 
                                ? 'Due today'
                                : `Due ${formatDueDate(task.dueDate)}`
                            }
                          </span>
                        )}
                      </div>
                    </div>
                    
                    {task.description && (
                      <p className="text-white/60 text-sm mb-3">
                        {task.description}
                      </p>
                    )}
                    
                    <div className="mt-3">
                      <div className="flex items-center mb-1">
                        <span className="text-xs text-white/60 mr-2">Progress:</span>
                        <span className="text-xs font-medium text-white">{task.progress}%</span>
                      </div>
                      <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                        <div
                          className={`h-full rounded-full transition-all duration-500 ease-out ${
                            task.completed
                              ? 'bg-green-500'
                              : task.progress > 66
                                ? 'bg-blue-500'
                                : task.progress > 33
                                  ? 'bg-yellow-500'
                                  : 'bg-orange-500'
                          }`}
                          style={{ width: `${task.progress}%` }}
                        ></div>
                      </div>
                    </div>
                    
                    {!task.completed && (
                      <div className="flex items-center mt-4 space-x-2">
                        {[0, 25, 50, 75, 100].map(value => (
                          <button
                            key={value}
                            onClick={() => handleProgressChange(task.id, value)}
                            className={`h-7 w-7 rounded-md text-xs transition-colors ${
                              task.progress === value
                                ? 'bg-blue-500 text-white'
                                : 'bg-white/10 hover:bg-white/20 text-white/70'
                            }`}
                          >
                            {value}%
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                  
                  <div className="ml-3 flex space-x-1">
                    <button
                      onClick={() => handleEdit(task)}
                      className="p-1.5 text-white/60 hover:text-white rounded-md hover:bg-white/10 transition-colors"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                      </svg>
                    </button>
                    <button
                      onClick={() => handleDelete(task.id)}
                      className="p-1.5 text-white/60 hover:text-red-400 rounded-md hover:bg-white/10 transition-colors"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default TaskManagement; 