import React, { useState, useEffect, useRef, useCallback } from 'react';
import { IconPomodoro, IconPlay, IconPause, IconReset } from '../../assets/icons';

const TIMER_TYPES = {
  POMODORO: 'pomodoro',
  SHORT_BREAK: 'shortBreak',
  CUSTOM: 'custom',
  STOPWATCH: 'stopwatch'
};

const DEFAULT_DURATIONS = {
  [TIMER_TYPES.POMODORO]: 25 * 60, // 25 minutes in seconds
  [TIMER_TYPES.SHORT_BREAK]: 5 * 60, // 5 minutes in seconds
  [TIMER_TYPES.CUSTOM]: 30 * 60 // Default custom timer: 30 minutes
};

const PomodoroTimer = () => {
  // Timer state
  const [activeTimer, setActiveTimer] = useState(TIMER_TYPES.POMODORO);
  const [timeLeft, setTimeLeft] = useState(DEFAULT_DURATIONS[TIMER_TYPES.POMODORO]);
  const [isRunning, setIsRunning] = useState(false);
  
  // Stopwatch state
  const [elapsedTime, setElapsedTime] = useState(0);
  
  // Custom timer state
  const [customMinutes, setCustomMinutes] = useState(30);
  const [customSeconds, setCustomSeconds] = useState(0);
  
  // Task assignment
  const [currentTask, setCurrentTask] = useState('');
  const [enteredTask, setEnteredTask] = useState('');
  
  // References
  const timerRef = useRef(null);
  const audioRef = useRef(null);

  // Convert seconds to minutes:seconds format
  const formatTime = useCallback((totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }, []);

  // Set up appropriate timer based on selected timer type
  useEffect(() => {
    if (activeTimer === TIMER_TYPES.CUSTOM) {
      setTimeLeft(customMinutes * 60 + customSeconds);
    } else if (activeTimer !== TIMER_TYPES.STOPWATCH) {
      setTimeLeft(DEFAULT_DURATIONS[activeTimer]);
    }
    
    if (isRunning) {
      stopTimer();
      startTimer();
    }
  }, [activeTimer, customMinutes, customSeconds]);

  // Timer functionality
  const startTimer = useCallback(() => {
    if (timerRef.current) return;
    
    if (activeTimer === TIMER_TYPES.STOPWATCH) {
      timerRef.current = setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    } else {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            playSound();
            stopTimer();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    
    setIsRunning(true);
  }, [activeTimer]);

  const stopTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setIsRunning(false);
  }, []);

  const resetTimer = useCallback(() => {
    stopTimer();
    
    if (activeTimer === TIMER_TYPES.STOPWATCH) {
      setElapsedTime(0);
    } else if (activeTimer === TIMER_TYPES.CUSTOM) {
      setTimeLeft(customMinutes * 60 + customSeconds);
    } else {
      setTimeLeft(DEFAULT_DURATIONS[activeTimer]);
    }
  }, [activeTimer, customMinutes, customSeconds]);

  const playSound = () => {
    if (audioRef.current) {
      audioRef.current.play().catch(error => console.error('Audio play failed:', error));
    }
  };

  const handleTimerToggle = () => {
    if (isRunning) {
      stopTimer();
    } else {
      startTimer();
    }
  };

  const handleTaskAssignment = (e) => {
    e.preventDefault();
    setCurrentTask(enteredTask);
    setEnteredTask('');
  };

  // Timer selector buttons
  const renderTimerSelector = () => (
    <div className="flex flex-wrap justify-center gap-2 mb-6">
      <button
        onClick={() => setActiveTimer(TIMER_TYPES.POMODORO)}
        className={`px-4 py-2 rounded-lg transition-all duration-300 ${
          activeTimer === TIMER_TYPES.POMODORO
            ? 'bg-indigo-600 text-white shadow-lg'
            : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
        }`}
      >
        Pomodoro (25m)
      </button>
      <button
        onClick={() => setActiveTimer(TIMER_TYPES.SHORT_BREAK)}
        className={`px-4 py-2 rounded-lg transition-all duration-300 ${
          activeTimer === TIMER_TYPES.SHORT_BREAK
            ? 'bg-green-600 text-white shadow-lg'
            : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
        }`}
      >
        Short Break (5m)
      </button>
      <button
        onClick={() => setActiveTimer(TIMER_TYPES.CUSTOM)}
        className={`px-4 py-2 rounded-lg transition-all duration-300 ${
          activeTimer === TIMER_TYPES.CUSTOM
            ? 'bg-purple-600 text-white shadow-lg'
            : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
        }`}
      >
        Custom Timer
      </button>
      <button
        onClick={() => {
          setActiveTimer(TIMER_TYPES.STOPWATCH);
          setElapsedTime(0);
        }}
        className={`px-4 py-2 rounded-lg transition-all duration-300 ${
          activeTimer === TIMER_TYPES.STOPWATCH
            ? 'bg-blue-600 text-white shadow-lg'
            : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
        }`}
      >
        Stopwatch
      </button>
    </div>
  );

  // Custom timer controls
  const renderCustomTimerControls = () => (
    <div className={`mb-6 transition-all duration-500 ${activeTimer === TIMER_TYPES.CUSTOM ? 'opacity-100 max-h-60' : 'opacity-0 max-h-0 overflow-hidden'}`}>
      <div className="bg-gray-800 rounded-lg p-4 flex flex-col sm:flex-row items-center gap-4">
        <div className="w-full sm:w-auto">
          <label htmlFor="minutes" className="block text-gray-400 mb-1 text-sm">Minutes</label>
          <input
            id="minutes"
            type="number"
            min="0"
            max="180"
            value={customMinutes}
            onChange={(e) => setCustomMinutes(parseInt(e.target.value) || 0)}
            className="w-24 px-3 py-2 bg-gray-700 rounded border border-gray-600 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>
        <div className="w-full sm:w-auto">
          <label htmlFor="seconds" className="block text-gray-400 mb-1 text-sm">Seconds</label>
          <input
            id="seconds"
            type="number"
            min="0"
            max="59"
            value={customSeconds}
            onChange={(e) => setCustomSeconds(parseInt(e.target.value) || 0)}
            className="w-24 px-3 py-2 bg-gray-700 rounded border border-gray-600 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>
      </div>
    </div>
  );

  // Task assignment
  const renderTaskAssignment = () => (
    <div className="mb-6">
      <form onSubmit={handleTaskAssignment} className="flex flex-col sm:flex-row gap-2">
        <input
          type="text"
          placeholder="What are you working on?"
          value={enteredTask}
          onChange={(e) => setEnteredTask(e.target.value)}
          className="flex-grow px-4 py-2 bg-gray-700 rounded-lg border border-gray-600 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
        />
        <button
          type="submit"
          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded-lg text-white transition-colors"
        >
          Set Task
        </button>
      </form>
      {currentTask && (
        <div className="mt-3 p-3 bg-gray-800 rounded-lg border border-gray-700">
          <p className="text-sm text-gray-400">Current Task:</p>
          <p className="text-white font-medium">{currentTask}</p>
        </div>
      )}
    </div>
  );

  // Main timer display
  const renderTimerDisplay = () => {
    const isStopwatch = activeTimer === TIMER_TYPES.STOPWATCH;
    const displayTime = isStopwatch ? formatTime(elapsedTime) : formatTime(timeLeft);
    
    let bgColorClass = '';
    if (isStopwatch) {
      bgColorClass = 'from-blue-900 to-blue-700';
    } else if (activeTimer === TIMER_TYPES.POMODORO) {
      bgColorClass = 'from-indigo-900 to-indigo-700';
    } else if (activeTimer === TIMER_TYPES.SHORT_BREAK) {
      bgColorClass = 'from-green-900 to-green-700';
    } else if (activeTimer === TIMER_TYPES.CUSTOM) {
      bgColorClass = 'from-purple-900 to-purple-700';
    }

    return (
      <div className={`w-full max-w-xs mx-auto mb-8 bg-gradient-to-br ${bgColorClass} rounded-xl shadow-lg p-8 text-center ring-1 ring-gray-700`}>
        <div className="mb-2">
          <IconPomodoro size={32} className="inline-block text-white opacity-80" />
        </div>
        <div className="font-mono text-5xl font-bold text-white tracking-wider mb-4">
          {displayTime}
        </div>
        <div className="flex justify-center gap-3">
          <button
            onClick={handleTimerToggle}
            className="p-2 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full text-white transition-all"
            aria-label={isRunning ? "Pause" : "Start"}
          >
            {isRunning ? (
              <IconPause size={24} />
            ) : (
              <IconPlay size={24} />
            )}
          </button>
          <button
            onClick={resetTimer}
            className="p-2 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full text-white transition-all"
            aria-label="Reset"
          >
            <IconReset size={24} />
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="p-4 md:p-6 max-w-4xl mx-auto">
      <h2 className="text-2xl font-bold text-white mb-6 text-center">Pomodoro Timer</h2>
      
      {/* Timer type selection */}
      {renderTimerSelector()}
      
      {/* Custom timer controls */}
      {renderCustomTimerControls()}
      
      {/* Task assignment */}
      {renderTaskAssignment()}
      
      {/* Timer display */}
      {renderTimerDisplay()}
      
      {/* Information section */}
      <div className="mt-8 bg-gray-800 bg-opacity-50 rounded-lg p-4 text-gray-300 text-sm">
        <h3 className="font-medium text-white mb-2">How to use the Pomodoro Technique:</h3>
        <ol className="list-decimal list-inside space-y-1 ml-2">
          <li>Choose a task you want to complete</li>
          <li>Set the Pomodoro timer (25 minutes)</li>
          <li>Work on the task until the timer rings</li>
          <li>Take a short break (5 minutes)</li>
          <li>After 4 Pomodoros, take a longer break (15-30 minutes)</li>
        </ol>
      </div>
      
      {/* Sound alert when timer completes */}
      <audio ref={audioRef} preload="auto">
        <source src="https://assets.mixkit.co/sfx/preview/mixkit-alarm-digital-clock-beep-989.mp3" type="audio/mpeg" />
        Your browser does not support the audio element.
      </audio>
    </div>
  );
};

export default PomodoroTimer;
