import React from 'react';
import {
  IconDashboard,
  IconMessages,
  IconNotifications,
  IconProfile,
  IconTasks,
  IconPomodoro,
  IconBook
} from '../../assets/icons';

const TabNavigation = ({ activeTab, setActiveTab }) => {
  const tabs = [
    { 
      id: 'dashboard', 
      label: 'Dashboard',
      icon: <IconDashboard size={20} className="mr-2" />
    },
    { 
      id: 'tasks', 
      label: 'Tasks',
      icon: <IconTasks size={20} className="mr-2" /> 
    },
    { 
      id: 'pomodoro', 
      label: 'Pomodoro',
      icon: <IconPomodoro size={20} className="mr-2" /> 
    },
    { 
      id: 'books', 
      label: 'Books',
      icon: <IconBook size={20} className="mr-2" /> 
    },
    { 
      id: 'messages', 
      label: 'Messages',
      icon: <IconMessages size={20} className="mr-2" /> 
    },
    { 
      id: 'notifications', 
      label: 'Notifications',
      icon: <IconNotifications size={20} className="mr-2" /> 
    },
    { 
      id: 'profile', 
      label: 'Profile',
      icon: <IconProfile size={20} className="mr-2" /> 
    }
  ];

  return (
    <div className="bg-white/5 backdrop-blur-xl rounded-2xl overflow-hidden shadow-lg shadow-black/10 border border-white/10 flex flex-wrap">
      {tabs.map(tab => (
        <button
          key={tab.id}
          className={`px-4 py-3.5 font-medium transition-all duration-300 relative overflow-hidden flex items-center ${
            activeTab === tab.id 
              ? 'text-white bg-white/10' 
              : 'text-white/70 hover:text-white hover:bg-white/5'
          }`}
          onClick={() => setActiveTab(tab.id)}
        >
          {tab.icon}
          {tab.label}
          {activeTab === tab.id && (
            <span className="absolute bottom-0 left-1/2 transform -translate-x-1/2 w-5 h-0.5 bg-gradient-to-r from-blue-400 to-blue-600 rounded-t-sm" />
          )}
        </button>
      ))}
    </div>
  );
};

export default TabNavigation; 